def chains_for(sk):
 pts=set(map(tuple,np.argwhere(sk)))
 adj={p:[] for p in pts}
 for y,x in pts:
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    if not (dy or dx): continue
    q=(y+dy,x+dx)
    if q not in pts:continue
    if dy and dx and ((y,x+dx) in pts or (y+dy,x) in pts):continue
    adj[(y,x)].append(q)
 nodes={p for p in pts if len(adj[p])!=2}
 visited=set(); out=[]
 def edge(a,b): return tuple(sorted((a,b)))
 for st in nodes:
  for nb in adj[st]:
   if edge(st,nb) in visited:continue
   seq=[st]; prev=st; cur=nb; visited.add(edge(st,nb))
   while 1:
    seq.append(cur)
    if cur in nodes:break
    nxt=[z for z in adj[cur] if z!=prev]
    if not nxt:break
    z=nxt[0]; visited.add(edge(cur,z)); prev,cur=cur,z
   out.append(seq)
 for p in pts:
  for nb in adj[p]:
   if edge(p,nb) in visited:continue
   seq=[p]; prev=p; cur=nb;visited.add(edge(p,nb))
   while cur!=p:
    seq.append(cur)
    nxt=[z for z in adj[cur] if z!=prev]
    if not nxt:break
    z=nxt[0];visited.add(edge(cur,z));prev,cur=cur,z
   seq.append(cur);out.append(seq)
 return out,adj
